{
  "name": "oc-codex-multi-account",
  "version": "1.0.20",
  "description": "Codex multi-account plugin with sticky threshold switching",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": "./dist/index.js"
  },
  "bin": {
    "oc-codex-multi-account": "dist/cli.js"
  },
  "scripts": {
    "build": "tsc",
    "clean": "rm -rf dist",
    "prepublishOnly": "bun run clean && bun run build",
    "web": "node ./dist/cli.js web --port 3434 --host 127.0.0.1"
  },
  "dependencies": {
    "@effect/cli": "0.67.1",
    "@effect/platform": "0.88.1",
    "@effect/platform-node": "0.88.1",
    "@openauthjs/openauth": "^0.4.3",
    "effect": "3.19.18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.150"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.193",
    "@opencode-ai/sdk": "^1.0.193",
    "@types/node": "^22.10.2",
    "typescript": "^5.7.2"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/gaboe/oc-codex-multi-account.git"
  },
  "bugs": {
    "url": "https://github.com/gaboe/oc-codex-multi-account/issues"
  },
  "homepage": "https://github.com/gaboe/oc-codex-multi-account#readme",
  "keywords": [
    "opencode",
    "openai",
    "codex",
    "oauth",
    "multi-account"
  ],
  "author": "gaboe",
  "license": "MIT"
}
